import { useCart } from "./CartContext";
import { useNavigate } from "react-router-dom";
import Ao1 from "../images/ao1.jpg";
import Ao3 from "../images/ao3.jpg";
import Ao4 from "../images/ao4.jpeg";
import Ao5 from "../images/ao5.jpeg";
import Ao6 from "../images/ao6.jpeg";

const recommendedProducts = [
    { id: 4, name: "Áo Polo Nam", price: 999, image: Ao1 },
    { id: 5, name: "Áo Polo Nam", price: 899, image: Ao3 },
    { id: 7, name: "Áo Polo Nam", price: 799, image: Ao4 },
    { id: 8, name: "Áo Polo Nam", price: 799, image: Ao5 },
    { id: 9, name: "Áo Polo Nam", price: 799, image: Ao6 }
];

const Cart = () => {
    const { cart, removeFromCart, totalItems, totalPrice, checkout, addToCart } = useCart();
    const navigate = useNavigate();

    return (
        <div className="container my-5">
            <div className="row">
                {/* Cart Content */}
                <div className="col-md-8">
                    {/* Cart Items */}
                    <div className="card p-4 shadow-sm">
                        <h2>Giỏ Hàng</h2>
                        <h3>({totalItems}) sản phẩm</h3>

                        {cart.length === 0 ? (
                            <p>Giỏ hàng của bạn đang trống.</p>
                        ) : (
                            <div>
                                {cart.map((product) => (
                                    <div key={product.id} className="d-flex justify-content-between align-items-center py-3 border-bottom">
                                        <div className="d-flex align-items-center">
                                            <img src={product.image} alt={product.name} className="img-fluid" style={{ width: "80px", height: "80px", objectFit: "cover" }} />
                                            <span className="ms-3">{product.name} - {product.price}k</span>
                                        </div>
                                        <button className="btn btn-danger" onClick={() => removeFromCart(product.id)}>Xóa</button>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Checkout and Summary */}
                    {cart.length > 0 && (
                        <div className="card mt-4 p-4 shadow-sm">
                            <div className="d-flex justify-content-between align-items-center">
                                <h4>Tổng tiền: {totalPrice}k</h4>
                                <button
                                    className="btn btn-success"
                                    onClick={() => {
                                        checkout();
                                        navigate("/donhang");
                                    }}
                                >
                                    🛍 Thanh toán
                                </button>
                            </div>
                            <div className="mt-3 text-success">
                                <p>MIỄN PHÍ VỚI CÁC ĐƠN HÀNG TRỊ GIÁ 999k</p>
                                <p>Mọi đơn hàng trên hệ thống được giảm giá phí vận chuyển còn <strong>20.000VND</strong></p>
                            </div>
                        </div>
                    )}
                </div>

                {/* Recommended Products */}
                <div className="col-md-4">
                    <div className="card p-4 shadow-sm">
                        <h3>Sản phẩm gợi ý</h3>
                        <div className="row">
                            {recommendedProducts.map((product) => (
                                <div key={product.id} className="col-6 mb-3">
                                    <div className="card">
                                        <img src={product.image} alt={product.name} className="img-fluid" style={{ height: "150px", objectFit: "cover" }} />
                                        <div className="card-body text-center">
                                            <h5>{product.name} - {product.price}k</h5>
                                            <button className="btn btn-primary" onClick={() => addToCart(product)}>Thêm vào giỏ</button>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Cart;
